<?php
if(!function_exists('valid_email_address')) require_once '../config/security.php';
if(!isset($conn))require_once '../config/database.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);if(!$uid){header('Location: ../auth/login.php');exit;}$message='';$messageType='';$st=$conn->prepare('SELECT first_name,last_name,email FROM users WHERE id=? LIMIT 1');$st->bind_param('i',$uid);$st->execute();$user=$st->get_result()->fetch_assoc();$st->close();
if($_SERVER['REQUEST_METHOD']==='POST'){$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$email=strtolower(trim($_POST['email']??''));$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';if(!csrf_valid($_POST['csrf_token']??null)){$message='Your session expired. Refresh and try again.';$messageType='error';}elseif($first===''||$last===''||!valid_email_address($email)){$message='Enter a valid name and email address.';$messageType='error';}else{$check=$conn->prepare('SELECT id FROM users WHERE email=? AND id<>? LIMIT 1');$check->bind_param('si',$email,$uid);$check->execute();$exists=$check->get_result()->num_rows>0;$check->close();if($exists){$message='That email address is already in use.';$messageType='error';}else{$st=$conn->prepare('UPDATE users SET first_name=?,last_name=?,email=? WHERE id=?');$st->bind_param('sssi',$first,$last,$email,$uid);$st->execute();$st->close();if($new!==''){$st=$conn->prepare('SELECT password FROM users WHERE id=?');$st->bind_param('i',$uid);$st->execute();$hash=$st->get_result()->fetch_assoc()['password']??'';$st->close();if(!password_verify($current,$hash)){$message='Your current password is incorrect.';$messageType='error';}elseif(!valid_strong_password($new)){$message='New password must be at least 8 characters and include uppercase, lowercase, a number, and a special character.';$messageType='error';}else{$hash=password_hash($new,PASSWORD_DEFAULT);$st=$conn->prepare('UPDATE users SET password=? WHERE id=?');$st->bind_param('si',$hash,$uid);$st->execute();$st->close();}}if(!$message){$_SESSION['first_name']=$first;$_SESSION['last_name']=$last;$_SESSION['email']=$email;$user=['first_name'=>$first,'last_name'=>$last,'email'=>$email];$message='Profile settings updated.';$messageType='success';}}}}
require '../includes/ui.php';ui_header('Profile Settings',$role);ui_sidebar($role,'profile.php');?>
<div class="page-head"><div><div class="eyebrow"><?=e(strtoupper($role))?> PROFILE</div><h1>Profile Settings</h1><div class="muted">Update your account details. Leave the password fields blank if you do not want to change your password.</div></div></div><?php if($message)flash($messageType,$message);?><section class="profile-settings-grid"><div class="card profile-summary"><span class="profile-avatar-large"><?=e(strtoupper(substr($user['first_name']??'U',0,1)))?></span><h2><?=e(($user['first_name']??'').' '.($user['last_name']??''))?></h2><p><?=e(ucfirst($role))?></p><small><?=e($user['email']??'')?></small></div><div class="card"><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>First Name</label><input name="first_name" value="<?=e($user['first_name']??'')?>" required></div><div class="field"><label>Last Name</label><input name="last_name" value="<?=e($user['last_name']??'')?>" required></div><div class="field full"><label>Email Address</label><input type="email" name="email" value="<?=e($user['email']??'')?>" required></div><div class="field"><label>Current Password</label><input type="password" name="current_password" autocomplete="current-password"></div><div class="field"><label>New Password</label><input type="password" name="new_password" autocomplete="new-password"></div><div class="actions full"><button class="btn btn-primary">Save Changes</button></div></form></div></section><?php ui_footer();?>
